<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Students Attendance</h1><p>Mark one class or every active student in a single register.</p></div></header><section class="module-card"><header class="module-card__header"><div><h2><?=($selectedScope??'class')==='all'?'All Students Attendance':'Class Attendance'?></h2><p>Late and Leave remain distinct from Present and Absent.</p></div></header><div class="module-card__body">
<form class="filter-bar" method="get"><div class="module-field"><label>Date</label><input class="module-input" name="date" type="date" value="<?=e($selectedDate)?>" required></div><div class="module-field"><label>View</label><select class="module-select" id="attendanceScope" name="scope"><option value="class" <?=($selectedScope??'class')==='class'?'selected':''?>>Specific class</option><option value="all" <?=($selectedScope??'class')==='all'?'selected':''?>>All students</option></select></div><div class="module-field" id="attendanceClassField"><label>Class</label><select class="module-select" name="class"><option value="">Select class</option><?php foreach($classes as$c):?><option value="<?=$c['id']?>" <?=$selectedClass===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></div><button class="btn btn--primary">Load Students</button></form>
<?php if(($selectedScope??'class')==='all'||$selectedClass):?><form method="post" action="<?=url('/admin/attendance/students')?>"><?=csrf_field()?><input type="hidden" name="date" value="<?=e($selectedDate)?>"><input type="hidden" name="scope" value="<?=e($selectedScope??'class')?>"><input type="hidden" name="class" value="<?=$selectedClass?>"><?php if(!$attendanceRows):?><div class="compact-empty"><h3>No active students found</h3></div><?php else:?><div class="table-tools"><span><strong><?=count($attendanceRows)?></strong> students loaded</span><button class="btn btn--secondary" type="button" onclick="document.querySelectorAll('.student-status').forEach(x=>x.value='Present')">Mark All Present</button></div><div class="table-scroll attendance-scroll"><table class="data-table attendance-table"><thead><tr><th>Registration</th><th>Student</th><?php if(($selectedScope??'class')==='all'):?><th>Class</th><?php endif?><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($attendanceRows as$row):?><tr><td data-label="Reg #"><?=e($row['registration_no'])?></td><td data-label="Student" class="att-name"><strong><?=e($row['student_name'])?></strong><?php require BASE_PATH.'/app/Views/partials/person-status-tag.php'; ?></td><?php if(($selectedScope??'class')==='all'):?><td data-label="Class"><?=e($row['class_name'])?></td><?php endif?><td data-label="Status"><select class="module-select student-status" name="status[<?=$row['id']?>]"><?php foreach(['Present','Absent','Late','Leave']as$s):?><option <?=$row['attendance_status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select></td><td data-label="Remarks"><input class="module-input" placeholder="Optional" name="remarks[<?=$row['id']?>]" value="<?=e($row['remarks'])?>"></td></tr><?php endforeach?></tbody></table></div><div class="module-card__footer attendance-save"><button class="btn btn--primary">Save Attendance for <?=count($attendanceRows)?> Students</button></div><?php endif?></form><?php endif?></div></section></div></div></main>
<script>document.addEventListener('DOMContentLoaded',()=>{const s=document.getElementById('attendanceScope'),f=document.getElementById('attendanceClassField'),c=f.querySelector('select');const sync=()=>{f.hidden=s.value==='all';c.required=s.value!=='all'};s.addEventListener('change',sync);sync()});</script>
